/* ---------- Helpers ---------- */

const euro = (n) =>
  new Intl.NumberFormat("nl-NL", { style: "currency", currency: "EUR", minimumFractionDigits: 2 }).format(n || 0);
const euro0 = (n) =>
  new Intl.NumberFormat("nl-NL", { style: "currency", currency: "EUR", maximumFractionDigits: 0 }).format(n || 0);

const longDate = (iso) =>
  new Date(iso + "T00:00:00").toLocaleDateString("nl-NL", { day: "numeric", month: "long" });
const shortDate = (iso) =>
  new Date(iso + "T00:00:00").toLocaleDateString("nl-NL", { day: "numeric", month: "short" });

const startOfToday = () => {
  const d = new Date();
  d.setHours(0, 0, 0, 0);
  return d;
};
const daysUntil = (iso) => Math.round((new Date(iso + "T00:00:00") - startOfToday()) / 86400000);

const toISO = (d) => {
  const z = new Date(d);
  return z.getFullYear() + "-" + String(z.getMonth() + 1).padStart(2, "0") + "-" + String(z.getDate()).padStart(2, "0");
};
const addDaysISO = (iso, n) => {
  const d = new Date(iso + "T00:00:00");
  d.setDate(d.getDate() + n);
  return toISO(d);
};
// Bespreking-data: eerste op za 4 juli, daarna elke zondag t/m 13 sep.
const MEETINGS = ["2026-07-04", "2026-07-12", "2026-07-19", "2026-07-26", "2026-08-02", "2026-08-09", "2026-08-16", "2026-08-23", "2026-08-30", "2026-09-06", "2026-09-13"];
// De bespreking waar een taak vóór moet: eerste besprekingsdatum op of na de deadline.
const besprekingFor = (iso) => MEETINGS.find((m) => m >= iso) || MEETINGS[MEETINGS.length - 1];

