/* ---------- Background music (uploaded track, looped) ---------- */
function fadeAudio(a, target, ms, done) {
  if (a._ft) clearInterval(a._ft);
  const start = a.volume;
  const t0 = typeof performance !== "undefined" ? performance.now() : Date.now();
  a._ft = setInterval(() => {
    const now = typeof performance !== "undefined" ? performance.now() : Date.now();
    const k = Math.min(1, (now - t0) / ms);
    a.volume = Math.max(0, Math.min(1, start + (target - start) * k));
    if (k >= 1) { clearInterval(a._ft); a._ft = null; if (done) done(); }
  }, 40);
}

function useHarpMusic() {
  const [playing, setPlaying] = useState(false);
  const ref = useRef(null);

  const toggle = () => {
    let a = ref.current;
    if (!a) {
      a = ref.current = new Audio(AUDIO_SRC);
      a.loop = true;
      a.preload = "auto";
      a.volume = 0;
    }
    if (playing) {
      fadeAudio(a, 0, 600, () => { try { a.pause(); } catch (e) {} });
      setPlaying(false);
    } else {
      a.volume = 0;
      const p = a.play();
      if (p && p.then) p.then(() => fadeAudio(a, 0.85, 900)).catch(() => {});
      else fadeAudio(a, 0.85, 900);
      setPlaying(true);
    }
  };

  useEffect(() => () => {
    const a = ref.current;
    if (a) { if (a._ft) clearInterval(a._ft); try { a.pause(); } catch (e) {} }
  }, []);

  return [playing, toggle];
}

function VinylButton({ playing, onToggle }) {
  return (
    <button className={"wp-vinyl" + (playing ? " is-spinning" : "")} onClick={onToggle} aria-label={playing ? "Muziek uit" : "Muziek aan"} title={playing ? "Zachte harpmuziek uit" : "Zachte harpmuziek aan"}>
      <svg viewBox="0 0 48 48" aria-hidden="true">
        <g className="wp-vinyl-spin">
          <circle cx="24" cy="24" r="16" fill="#2e2622" />
          <circle cx="24" cy="24" r="11" fill="none" stroke="rgba(255,255,255,.16)" strokeWidth="1" />
          <circle cx="24" cy="24" r="7.5" fill="none" stroke="rgba(255,255,255,.16)" strokeWidth="1" />
          <circle cx="24" cy="24" r="4.5" fill="var(--rose)" />
          <line x1="24" y1="24" x2="24" y2="9" stroke="rgba(255,255,255,.22)" strokeWidth="1" />
        </g>
        <circle cx="24" cy="24" r="1.5" fill="#2e2622" stroke="#fff" strokeWidth="0.6" />
        <g>
          <line x1="39" y1="10" x2="28.5" y2="20.5" stroke="var(--brass)" strokeWidth="2.2" strokeLinecap="round" />
          <circle cx="39" cy="10" r="2.6" fill="var(--brass)" />
        </g>
      </svg>
    </button>
  );
}

export default function App() {
  const { data, setData, loaded } = useStore();
  const [tab, setTab] = useState("taken");
  const [now, setNow] = useState(new Date());
  const [musicOn, toggleMusic] = useHarpMusic();
  const [intro, setIntro] = useState(true);

  useEffect(() => {
    const t = setTimeout(() => setIntro(false), 3000);
    return () => clearTimeout(t);
  }, []);

  useEffect(() => {
    const t = setInterval(() => setNow(new Date()), 60000);
    return () => clearInterval(t);
  }, []);

  const allTasks = useMemo(() => {
    const edits = data.taskEdits || {};
    const removed = data.taskRemoved || {};
    return [...TASKS, ...data.customTasks]
      .filter((t) => !removed[t.id])
      .map((t) => (edits[t.id] ? { ...t, ...edits[t.id] } : t));
  }, [data.customTasks, data.taskEdits, data.taskRemoved]);
  const allGuests = useMemo(() => [...GUESTS, ...data.customGuests], [data.customGuests]);

  const daysToGo = daysUntil(WEDDING_ISO);

  return (
    <div className="wp-root">
      <style>{CSS}</style>

      {intro && (
        <div className="wp-intro" onClick={() => setIntro(false)} role="presentation">
          <div className="wp-intro-art" aria-hidden="true">
            <div className="wp-if-base" style={{ backgroundImage: `url(${FLORAL})` }} />
            <div className="wp-if-corner ic-tl" style={{ backgroundImage: `url(${FLORAL})` }} />
            <div className="wp-if-corner ic-tr" style={{ backgroundImage: `url(${FLORAL})` }} />
            <div className="wp-if-corner ic-bl" style={{ backgroundImage: `url(${FLORAL})` }} />
            <div className="wp-if-corner ic-br" style={{ backgroundImage: `url(${FLORAL})` }} />
            <div className="wp-intro-veil" />
          </div>
          <img className="wp-intro-mark" src={LOGO_CREST} alt="" />
        </div>
      )}

      <Hero daysToGo={daysToGo} musicOn={musicOn} onToggleMusic={toggleMusic} tab={tab} setTab={setTab} />

      <TabBar tab={tab} setTab={setTab} />

      <main className="wp-main">
        {!loaded && <p className="wp-loading">Planner laden…</p>}
        {loaded && tab === "taken" && <Tasks tasks={allTasks} data={data} setData={setData} />}
        {loaded && tab === "budget" && <Budget data={data} setData={setData} />}
        {loaded && tab === "gasten" && <Guests guests={allGuests} data={data} setData={setData} />}
        {loaded && tab === "schema" && <Schema data={data} setData={setData} />}
      </main>

      <footer className="wp-footer">
        <img className="wp-footer-mark" src={LOGO_MARK} alt="N & S Vermeer" />
      </footer>
    </div>
  );
}

